// Configurações de backup - PERSONALIZE AQUI
const BACKUP_CONFIG = {
  // Filtros opcionais - deixe vazio para fazer backup de todos
  includeOnlyTags: [], // Ex: ['production', 'backup'] 
  excludeTags: ['temp', 'test'], // Tags para excluir
  includeFolders: [], // Ex: ['Production', 'Important'] 
  excludeFolders: ['Archive', 'Temp'], // Pastas para excluir

  // Configurações do GitHub
  githubFolder: 'backup', // Pasta no GitHub (mantendo sua estrutura)
  includeInactive: true, // Incluir workflows inativos
};

// Processar workflows
const workflows = $input.all()[0].json.data || [];
const filteredWorkflows = [];

for (const workflow of workflows) {
  let shouldInclude = true;

  // Filtro por tags
  if (BACKUP_CONFIG.includeOnlyTags.length > 0) {
    const workflowTags = workflow.tags?.map(t => t.name) || [];
    shouldInclude = BACKUP_CONFIG.includeOnlyTags.some(tag => workflowTags.includes(tag));
  }

  if (BACKUP_CONFIG.excludeTags.length > 0) {
    const workflowTags = workflow.tags?.map(t => t.name) || [];
    shouldInclude = shouldInclude && !BACKUP_CONFIG.excludeTags.some(tag => workflowTags.includes(tag));
  }

  // Filtro por status ativo
  if (!BACKUP_CONFIG.includeInactive && !workflow.active) {
    shouldInclude = false;
  }

  if (shouldInclude) {
    filteredWorkflows.push({
      id: workflow.id,
      name: workflow.name,
      active: workflow.active,
      tags: workflow.tags || [],
      createdAt: workflow.createdAt,
      updatedAt: workflow.updatedAt
    });
  }
}

console.log(`🔍 Processando ${workflows.length} workflows, ${filteredWorkflows.length} selecionados para backup`);

return filteredWorkflows.map((workflow, index) => ({
  json: {
    ...workflow,
    batchIndex: index,
    totalWorkflows: filteredWorkflows.length,
    backupConfig: BACKUP_CONFIG
  }
}));

// Preparar dados do workflow para backup - ESTRUTURA CORRETA N8N
// Adaptado para sua implementação específica

const workflowData = $input.item.json; // Dados do workflow da API
const metadata = $input.item.json; // Metadados do item atual

// ⚠️ IMPORTANTE: Manter estrutura EXATA do n8n original (SEM WRAPPERS)
const backupWorkflow = {
  // Campos principais do workflow (estrutura n8n nativa)
  name: workflowData.name,
  nodes: workflowData.nodes || [],
  connections: workflowData.connections || {},
  active: workflowData.active || false,
  settings: workflowData.settings || {},
  staticData: workflowData.staticData || {},

  // Campos de metadados (nível raiz - CRÍTICO)
  id: workflowData.id,
  versionId: workflowData.versionId,
  tags: workflowData.tags || [],
  triggerCount: workflowData.triggerCount || 0,

  // Metadados da instância (se existirem)
  ...(workflowData.meta && { meta: workflowData.meta }),

  // PinData (dados de teste fixados) - CRÍTICO para funcionamento
  ...(workflowData.pinData && { pinData: workflowData.pinData }),

  // Adicionar informações de backup como comentário (não interfere na importação)
  "//backupInfo": {
    timestamp: new Date().toISOString(),
    originalId: workflowData.id,
    backupVersion: "2.0",
    restorable: true,
    backupSource: "n8n-github-backup-automation"
  }
};

// Gerar nome de arquivo seguro (preservando caracteres especiais importantes)
const safeName = workflowData.name
  .replace(/[^a-zA-Z0-9\s\-_\[\]()]/g, '') // Preserva colchetes e parênteses
  .replace(/\s+/g, '-')
  .toLowerCase()
  .replace(/--+/g, '-'); // Remove hífens duplos

const timestamp = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
const fileName = `${safeName}-${workflowData.id}.json`;
const githubPath = `backup/${timestamp}/${fileName}`; // Mantendo sua estrutura de pasta

// Converter para JSON formatado (compatível 100% com n8n)
const jsonContent = JSON.stringify(backupWorkflow, null, 2);

// Logs detalhados para debugging
console.log(`📦 Backup compatível N8N: ${workflowData.name}`);
console.log(`📁 Caminho GitHub: ${githubPath}`);
console.log(`🔧 Nós encontrados: ${(workflowData.nodes || []).length}`);
console.log(`📌 PinData preservado: ${workflowData.pinData ? 'Sim' : 'Não'}`);
console.log(`🏷️ Tags: ${(workflowData.tags || []).length}`);
console.log(`🆔 ID original: ${workflowData.id}`);
console.log(`📝 Version ID: ${workflowData.versionId || 'N/A'}`);

return {
  json: {
    fileName: fileName,
    githubPath: githubPath,
    content: jsonContent,
    workflowName: workflowData.name,
    workflowId: workflowData.id,
    isActive: workflowData.active,
    nodeCount: (workflowData.nodes || []).length,
    hasCredentials: (workflowData.nodes || []).some(node => node.credentials),
    hasPinData: !!workflowData.pinData,
    hasMetadata: !!workflowData.meta,
    backupTimestamp: timestamp,
    backupStructure: 'n8n-native' // Indica estrutura correta
  }
};

// Gerar relatório de backup
const items = $input.all();
const successful = [];
const failed = [];

for (const item of items) {
  if (item.json.error) {
    failed.push({
      name: item.json.content.nmw || 'Unknown',
      error: item.json.error
    });
  } else {
    successful.push({
      name: item.json.content.name,
      url: item.json.content.git_url,
      path: item.json.content.path,
    });
  }
}

const report = {
  timestamp: new Date().toISOString(),
  summary: {
    total: items.length,
    successful: successful.length,
    failed: failed.length,
    successRate: `${((successful.length / items.length) * 100).toFixed(1)}%`,
    withPinData: successful.filter(s => s.hasPinData).length,
    withCredentials: successful.filter(s => s.hasCredentials).length
  },
  successful: successful,
  failed: failed,
  repositoryInfo: {
    owner: 'orafaelalves', // Seu usuário GitHub
    repo: 'flouume-workflows', // Seu repositório
    folder: 'backup', // Sua pasta
    backupStructure: 'n8n-native-corrected'
  }
};

console.log('📊 RELATÓRIO DE BACKUP CORRIGIDO:');
console.log(`✅ Sucessos: ${successful.length}`);
console.log(`❌ Falhas: ${failed.length}`);
console.log(`📈 Taxa de sucesso: ${report.summary.successRate}`);
console.log(`📌 Com PinData: ${report.summary.withPinData}`);
console.log(`🔐 Com Credenciais: ${report.summary.withCredentials}`);

if (failed.length > 0) {
  console.log('\n❌ Workflows com falha:');
  failed.forEach(f => console.log(`  - ${f.name} (${f.id}): ${f.error}`));
}

return [{ json: report }];
